local AugerBitMaker = {}
local PRODUCTS = {
    iron_auger_bit = { name = "Železni svrder za vrtanje", ironCost = 5, woodCost = 1, leatherCost = 1, time = 5, cost = 195, prestige = 4, happiness = 2, description = "Železni svrder za vrtanje lukenj v les." },
    bronze_auger_bit = { name = "Bronast svrder za vrtanje", bronzeCost = 5, ironCost = 1, woodCost = 1, leatherCost = 1, time = 7, cost = 470, prestige = 6, happiness = 3, description = "Bronast svrder za natančno vrtanje." },
    silver_auger_bit = { name = "Srebrni svrder za vrtanje", silverCost = 5, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 11, cost = 1130, prestige = 11, happiness = 4, description = "Srebrni svrder za plemiške mizarje." },
    gilded_auger_bit = { name = "Pozlačeni svrder za vrtanje", goldCost = 1, silverCost = 5, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 15, cost = 2420, prestige = 20, happiness = 5, description = "Pozlačeni svrder za dvorne mizarje." },
    jewel_set_auger_bit = { name = "Draguljasti svrder za vrtanje", goldCost = 2, silverCost = 5, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 19, cost = 5200, prestige = 36, happiness = 7, description = "Draguljasti svrder za kraljevske mizarje." },
    royal_sovereign_auger_bit = { name = "Kraljevski suvereni svrder za vrtanje", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 26, cost = 11100, prestige = 69, happiness = 13, description = "Suvereni svrder z biseri za krono." },
}
local BUILDINGS = {
    augerbit_workshop = { name = "Vrtalna delavnica", cost = { gold = 380, wood = 175, stone = 150, iron = 11 }, upkeep = 7, qualityBonus = 5 },
    augerbit_house = { name = "Vrtalna hiša", cost = { gold = 1310, wood = 360, stone = 295, silver = 8, iron = 9 }, upkeep = 28, qualityBonus = 18 },
    master_augerbit_atelier = { name = "Mojstrski vrtalni atelje", cost = { gold = 3230, wood = 420, stone = 550, silver = 40, gold = 8 }, upkeep = 76, qualityBonus = 30 },
    sovereign_augerbit_palace = { name = "Suverena vrtalna palača", cost = { gold = 13800, wood = 655, stone = 870, gold = 89, jewel = 20 }, upkeep = 264, qualityBonus = 55, prestigeBonus = 50 },
}
AugerBitMaker.ironStock = 18; AugerBitMaker.bronzeStock = 14; AugerBitMaker.woodStock = 10; AugerBitMaker.leatherStock = 8; AugerBitMaker.silverStock = 8; AugerBitMaker.goldStock = 6; AugerBitMaker.jewelStock = 4; AugerBitMaker.pearlStock = 4
AugerBitMaker.productStock = {}; AugerBitMaker.buildings = {}; AugerBitMaker.maker = nil; AugerBitMaker.activeMaking = {}; AugerBitMaker.totalProducts = 0; AugerBitMaker.dayTimer = 0
function AugerBitMaker.init() AugerBitMaker.ironStock=18; AugerBitMaker.bronzeStock=14; AugerBitMaker.woodStock=10; AugerBitMaker.leatherStock=8; AugerBitMaker.silverStock=8; AugerBitMaker.goldStock=6; AugerBitMaker.jewelStock=4; AugerBitMaker.pearlStock=4; AugerBitMaker.productStock={}; AugerBitMaker.buildings={}; AugerBitMaker.maker=nil; AugerBitMaker.activeMaking={}; AugerBitMaker.totalProducts=0; AugerBitMaker.dayTimer=0; print("[AugerBitMaker] Royal Auger Bit Maker System initialized (6 products, 4 buildings)") end
function AugerBitMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; AugerBitMaker.maker={name=n or ("Vrtač "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vrtač najet: %s (spretnost: %d)",AugerBitMaker.maker.name,s),"success") end; return true end
function AugerBitMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function AugerBitMaker.build(id) local ok,e=AugerBitMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(AugerBitMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function AugerBitMaker.getQualityBonus() local b=0; for _,bd in ipairs(AugerBitMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function AugerBitMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and AugerBitMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and AugerBitMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and AugerBitMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and AugerBitMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and AugerBitMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and AugerBitMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and AugerBitMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and AugerBitMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #AugerBitMaker.buildings==0 then return false,"Potrebna vrtalna delavnica" end; if not AugerBitMaker.maker then return false,"Potreben vrtač" end; return true end
function AugerBitMaker.make(pt,qty) qty=qty or 1; local ok,e=AugerBitMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then AugerBitMaker.ironStock=AugerBitMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then AugerBitMaker.bronzeStock=AugerBitMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then AugerBitMaker.woodStock=AugerBitMaker.woodStock-d.woodCost*qty end; if d.leatherCost then AugerBitMaker.leatherStock=AugerBitMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then AugerBitMaker.silverStock=AugerBitMaker.silverStock-d.silverCost*qty end; if d.goldCost then AugerBitMaker.goldStock=AugerBitMaker.goldStock-d.goldCost*qty end; if d.jewelCost then AugerBitMaker.jewelStock=AugerBitMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then AugerBitMaker.pearlStock=AugerBitMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if AugerBitMaker.maker then t=math.max(1,t-math.floor(AugerBitMaker.maker.skill/13)) end; table.insert(AugerBitMaker.activeMaking,{id="augerbit_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function AugerBitMaker.completeMaking(m) local q=1.0+(AugerBitMaker.getQualityBonus()/100); if AugerBitMaker.maker then q=q+(AugerBitMaker.maker.skill/140) end; q=math.min(2.5,q); AugerBitMaker.productStock[m.productType]=(AugerBitMaker.productStock[m.productType] or 0)+m.quantity; AugerBitMaker.totalProducts=AugerBitMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if AugerBitMaker.maker then AugerBitMaker.maker.itemsMade=AugerBitMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then AugerBitMaker.maker.skill=math.min(100,AugerBitMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Svrder izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"augerbit.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function AugerBitMaker.update(dt) if not _G.state then return end; AugerBitMaker.dayTimer=AugerBitMaker.dayTimer+dt; if AugerBitMaker.dayTimer>=30 then AugerBitMaker.dayTimer=0; for i=#AugerBitMaker.activeMaking,1,-1 do local m=AugerBitMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then AugerBitMaker.completeMaking(m); table.remove(AugerBitMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(AugerBitMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if AugerBitMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function AugerBitMaker.getStats() return {ironStock=AugerBitMaker.ironStock,bronzeStock=AugerBitMaker.bronzeStock,woodStock=AugerBitMaker.woodStock,leatherStock=AugerBitMaker.leatherStock,silverStock=AugerBitMaker.silverStock,goldStock=AugerBitMaker.goldStock,jewelStock=AugerBitMaker.jewelStock,pearlStock=AugerBitMaker.pearlStock,productStock=AugerBitMaker.productStock,numBuildings=#AugerBitMaker.buildings,hasMaker=AugerBitMaker.maker~=nil,makerName=AugerBitMaker.maker and AugerBitMaker.maker.name or "—",makerSkill=AugerBitMaker.maker and AugerBitMaker.maker.skill or 0,activeMaking=#AugerBitMaker.activeMaking,totalProducts=AugerBitMaker.totalProducts} end
return AugerBitMaker
